59	/**
60	 * Minimal in-memory localStorage stub for the Node/vm context.
61	 *
62	 * project-list.js accesses `localStorage` as a bare global name.  Inside
63	 * `vm.runInThisContext` the lookup resolves against the Node global object, not
64	 * the jsdom window — so `window.localStorage` is invisible.  We install a
65	 * lightweight stub directly on `global` so the script can read and write
66	 * without throwing.
67	 */
68	function makeLocalStorageStub() {
69	  const store: Record<string, string> = {};
70	  return {
71	    getItem:    (k: string) => store[k] ?? null,
72	    setItem:    (k: string, v: string) => { store[k] = String(v); },
73	    removeItem: (k: string) => { delete store[k]; },
74	    clear:      () => { for (const k in store) delete store[k]; },
75	  };
76	}
